package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Arrays;
import java.util.function.IntUnaryOperator;
import org.eclipse.rdf4j.sail.lmdb.LmdbQueryMemoryManager;
import org.junit.jupiter.api.Test;

class NativeSegmentedTupleTableTest {
	private static long[] row(int i) {
		long[] key = new long[30];
		Arrays.fill(key, i);
		key[0] = Long.MIN_VALUE; key[29] = Long.MAX_VALUE;
		return key;
	}

	@Test void chunkAndDirectoryGrowthPreserveKeysAndClear() {
		var manager = LmdbQueryMemoryManager.createForTesting(2_000_000, 2_000_000);
		try (var ledger = manager.openQuery(); var table = new NativeSegmentedTupleTable(30, ledger)) {
			for (int i = 0; i < 5000; i++) assertEquals(1, table.add(row(i)));
			for (int i = 0; i < 5000; i++) {
				assertEquals(0, table.add(row(i)));
				assertEquals(i, table.key(i, 1));
				assertEquals(Long.MIN_VALUE, table.key(i, 0));
			}
			long retained = ledger.usedBytes();
			table.clear();
			for (int i = 4999; i >= 0; i--) assertEquals(1, table.add(row(i)));
			assertEquals(retained, ledger.usedBytes());
			assertTrue(manager.peakUsedBytes() < 1_400_000, "no doubled payload arrays");
		}
		assertEquals(0, manager.usedBytes());
	}

	@Test void collisionsAndInjectedBucketCeilingRefuseWithoutLosingKeys() {
		var manager = LmdbQueryMemoryManager.createForTesting(100_000, 100_000);
		try (var ledger = manager.openQuery(); var table = new NativeSegmentedTupleTable(30, ledger, 4, h -> 1)) {
			for (int i = 0; i < 3; i++) assertEquals(1, table.add(row(i)));
			long retained = ledger.usedBytes();
			assertEquals(-1, table.add(row(3)));
			assertEquals(3, table.size);
			for (int i = 0; i < 3; i++) assertEquals(0, table.add(row(i)));
			assertEquals(retained, ledger.usedBytes(), "duplicates do not request growth");
			table.clear();
			for (int i = 2; i >= 0; i--) assertEquals(1, table.add(row(i)));
		}
		assertEquals(0, manager.usedBytes());
	}

	@Test void refusedChunkGrowthPreservesExistingInsertionOrder() {
		var manager = LmdbQueryMemoryManager.createForTesting(70_000, 70_000);
		try (var ledger = manager.openQuery(); var table = new NativeSegmentedTupleTable(30, ledger)) {
			for (int i = 0; i < 256; i++) assertEquals(1, table.add(row(i)));
			assertEquals(-1, table.add(row(256)));
			assertEquals(256, table.size);
			for (int i = 0; i < 256; i++) {
				assertEquals(0, table.add(row(i)));
				assertEquals(i, table.key(i, 1));
			}
			assertTrue(manager.peakUsedBytes() <= 70_000);
		}
		assertEquals(0, manager.usedBytes());
	}

	@Test void invalidCapacityAndWidthCannotOverflowArrayArithmetic() {
		var manager = LmdbQueryMemoryManager.createForTesting(100_000, 100_000);
		try (var ledger = manager.openQuery()) {
			assertThrows(IllegalArgumentException.class, () -> new NativeSegmentedTupleTable(Integer.MAX_VALUE, ledger));
			assertThrows(IllegalArgumentException.class, () -> new NativeSegmentedTupleTable(30, ledger, Integer.MAX_VALUE, IntUnaryOperator.identity()));
			assertEquals(0, ledger.usedBytes());
		}
	}
}
